import fs from 'fs';

import { resolveGlobalConfigDir, resolveGlobalConfigPath, resolveLocalEnvPath } from './paths.js';

const KEY_NAME = 'OPENAI_API_KEY';
const LINE_PATTERN = /^(\s*(?:export\s+)?)OPENAI_API_KEY\s*=(.*)$/;

const ensureDir = (dirPath) => {
  if (!fs.existsSync(dirPath)) {
    fs.mkdirSync(dirPath, { recursive: true, mode: 0o700 });
  }
};

const sanitizeValue = (value) => {
  if (typeof value !== 'string') return null;
  return value.trim() || null;
};

// Value part of a .env assignment: optional quotes, trailing `# comment`.
const parseEnvValue = (raw) => {
  const text = raw.trimStart();
  const quote = text[0];
  if (quote === '"' || quote === "'") {
    const end = text.indexOf(quote, 1);
    return end === -1 ? text.slice(1) : text.slice(1, end);
  }
  const hash = text.search(/(^|\s)#/);
  return (hash === -1 ? text : text.slice(0, hash)).trim();
};

// Split keeping line terminators: even indexes are lines, odd are terminators.
const findLastDefinition = (content) => {
  const parts = content.split(/(\r?\n)/);
  let index = -1;
  for (let i = 0; i < parts.length; i += 2) {
    if (LINE_PATTERN.test(parts[i])) index = i;
  }
  return { parts, index };
};

export const getLocalApiKey = (cwd = process.cwd()) => {
  const envPath = resolveLocalEnvPath(cwd);
  if (!fs.existsSync(envPath)) return null;
  const { parts, index } = findLastDefinition(fs.readFileSync(envPath, 'utf8'));
  if (index === -1) return null;
  return sanitizeValue(parseEnvValue(parts[index].match(LINE_PATTERN)[2]));
};

export const hasLocalApiKey = (cwd = process.cwd()) => getLocalApiKey(cwd) !== null;

export const setLocalApiKey = (key, cwd = process.cwd()) => {
  if (!key) throw new Error('API key is required');
  const envPath = resolveLocalEnvPath(cwd);
  const content = fs.existsSync(envPath) ? fs.readFileSync(envPath, 'utf8') : '';
  const { parts, index } = findLastDefinition(content);
  let next;
  if (index !== -1) {
    parts[index] = `${parts[index].match(LINE_PATTERN)[1]}${KEY_NAME}=${key}`;
    next = parts.join('');
  } else {
    const eol = content.includes('\r\n') ? '\r\n' : '\n';
    const sep = content && !content.endsWith('\n') ? eol : '';
    next = `${content}${sep}${KEY_NAME}=${key}${eol}`;
  }
  fs.writeFileSync(envPath, next, { encoding: 'utf8', mode: 0o600 });
  return envPath;
};

const readGlobalConfig = (configPath) => {
  if (!fs.existsSync(configPath)) return {};
  const content = fs.readFileSync(configPath, 'utf8');
  let parsed;
  try {
    parsed = JSON.parse(content);
  } catch (error) {
    throw new Error(`Global config at ${configPath} is not valid JSON; fix or remove it first.`);
  }
  if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) {
    throw new Error(`Global config at ${configPath} is not a JSON object; fix or remove it first.`);
  }
  return parsed;
};

export const getGlobalApiKey = (homeDir = process.env.HOME || process.env.USERPROFILE) => {
  const configPath = resolveGlobalConfigPath(homeDir);
  if (!fs.existsSync(configPath)) return null;
  try {
    return sanitizeValue(JSON.parse(fs.readFileSync(configPath, 'utf8'))[KEY_NAME]);
  } catch (error) {
    return null;
  }
};

export const hasGlobalApiKey = (homeDir = process.env.HOME || process.env.USERPROFILE) =>
  getGlobalApiKey(homeDir) !== null;

export const setGlobalApiKey = (key, homeDir = process.env.HOME || process.env.USERPROFILE) => {
  if (!key) throw new Error('API key is required');
  const configPath = resolveGlobalConfigPath(homeDir);
  const config = readGlobalConfig(configPath);
  ensureDir(resolveGlobalConfigDir(homeDir));
  const payload = JSON.stringify({ ...config, [KEY_NAME]: key }, null, 2);
  fs.writeFileSync(configPath, payload, { encoding: 'utf8', mode: 0o600 });
  return configPath;
};

