    }
    if (options.clean) {
        cleanDocs();
        return;
    }
    const exportOnly = options.exportPdf &&
        !options.scan &&
        !options.ci &&
        !options.setup &&
        !options.listDocs &&
        !options.clean &&
        !options.update &&
        !options.showConfig &&
        !options.key;
    if (exportOnly) {
        exportDocsAsPdf();
        return;
    }
    const showConfigOnly = options.showConfig &&
        !options.scan &&
        !options.ci &&
        !options.setup &&
        !options.listDocs &&
        !options.clean &&
        !options.update &&
        !options.exportPdf &&
        !options.key;
    if (showConfigOnly) {
